import test from'node:test';import assert from'node:assert/strict';import{createHash}from'node:crypto';
import{segmentedStereogram}from'../src/segmented-stereogram.js';import{previewCachedStereo}from'../src/cached-parameter-preview.js';import{stereoStreamMath}from'../src/stereo-stream-kernel.js';import{Budget}from'../src/cache.js';import{contiguousSurface}from'../src/image-sources.js';
const reference={"cases":[{"name":"repeat","file":"repeat.png","width":96,"height":33,"offset":12,"differences":[39.24781799316406,36.49117660522461,5.4464287757873535,36.91415786743164,38.33612823486328,40.60030746459961,37.349998474121094,39.95174026489258,40.21073532104492,39.539772033691406,37.220394134521484,40.55500030517578,35.70185852050781,36.89554977416992,12.708333015441895,37.25,34.42410659790039,40.11050796508789,37.29963302612305,40.030784606933594,40.52651596069336,39.519229888916016],"views":["2bebf5484af8895601c6322f2da117a73b1f92b84f3f1ff6feac91623529bdd5","b9862fa31c915f40e494fd12de29d543463f37b6320d89910741ae4be896129d","b6954e3041c1e4613c02943168d4e562108564047365b6fae5b44e08252cbf67","88fe41a9e6344e2aae4ad3e02afd2450da1fe0679d27165c30c0daf6b76303f3"],"flowSha256":"8d97bbee2e6e8613e3f1312b524c8fb3d03f07fba8335402d38cfb7627edd5f2","rgbBase64":""},{"name":"odd","file":"odd.png","width":197,"height":65,"offset":24,"differences":[37.418785095214844,37.843414306640625,38.252872467041016,37.79314041137695,37.39890670776367,38.73969650268555,38.74032974243164,37.872047424316406,38.916900634765625,38.73314666748047,39.988346099853516,37.463069915771484,36.22464370727539,37.90858459472656,5.290462493896484,37.950035095214844,35.69444274902344,37.52426528930664,39.85484313964844,38.5695686340332,38.78649139404297,37.8531608581543,38.82196807861328,38.735137939453125,37.43443298339844,37.84104919433594,38.13373565673828,37.783203125,37.411949157714844,38.8125,39.04737091064453,37.8828125,38.73024368286133,38.4224853515625,39.787174224853516,37.99013137817383,33.05463409423828,37.73979187011719,12.285234451293945,37.785682678222656,32.35161590576172,38.02696990966797,39.636207580566406,38.14756774902344,38.515953063964844,37.823062896728516,39.09219741821289,38.850669860839844,37.41142272949219,37.75294494628906,37.986083984375,37.771827697753906,37.4439811706543,38.84911346435547,39.32706832885742],"views":["0dfaf08653740032d0cb33c7dbe79189166d8ea02c76fda0c6f963a156cfc542","80e0aeb5d487a89cc5952f41fdda5abbaaa33a3cd06b918566f6f80f073cb964","9b844603c8fd1477f71f4116968c97ad8b0604bf4ba6715498ef2d6e9edf1728","0ddd4c08063472a8061381a075afa9408bee3cd6dcf1e9e33a21875a08fc00fa"],"flowSha256":"76446db7d7cda43507cdc5a3c4a3b8be7204d801ff07c4bbcc36573a3bfa252e","rgbBase64":""}]},hash=a=>createHash('sha256').update(new Uint8Array(a.buffer,a.byteOffset,a.byteLength)).digest('hex');
const fixture=async name=>{const e=reference.cases.find(x=>x.name===name),budget=new Budget(128*1024**2),data=Uint8Array.from(Buffer.from(e.rgbBase64,'base64'));return{e,budget,image:{surface:contiguousSurface({width:e.width,height:e.height,format:'rgb8',data},budget)}};};
const disposeResult=async r=>{await r.surface?.dispose();for(const v of Object.values(r.tableRecords??{}))await v.surface.dispose();};
test('Small exact pattern strips do not force a calendar timer for every row',async()=>{await stereoStreamMath();const f=await fixture('repeat'),old=setTimeout;let timers=0,r;globalThis.setTimeout=(fn,ms,...a)=>{if(ms===0)timers++;return old(fn,ms,...a);};try{r=await segmentedStereogram(f.image,{mode:0},{budget:f.budget,blockPixels:96});assert.ok(timers<20,'forced timers='+timers);const frame=await r.surface.readWindow();assert.equal(hash(frame.pixels.data),f.e.views[0]);frame.release();}finally{globalThis.setTimeout=old;await disposeResult(r??{});await r?.stereoCache.dispose();assert.equal(f.budget.total(),0);}});
test('Two fresh native fixtures: all modes and Float32 flow match the independent native oracle',async()=>{for(const e of reference.cases){const f=await fixture(e.name);let cache;try{for(const mode of e.offset===null?[0,3]:[0,2,1,3,0,3]){const r=await segmentedStereogram(f.image,{mode},{budget:f.budget,cache,blockPixels:1024});cache=r.stereoCache;assert.equal(r.data.offset,e.offset);assert.deepEqual([...r.data.differences],e.differences);if(e.offset!==null){const frame=await r.surface.readWindow();assert.equal(hash(frame.pixels.data),e.views[mode],e.name+'/'+mode);frame.release();if(mode>=2)assert.equal(hash(await cache.flow.plane.read(0,0,e.width-e.offset,e.height)),e.flowSha256);}await disposeResult(r);}}finally{await cache?.dispose();assert.equal(f.budget.total(),0,e.name);}}});
test('Published native lease survives dropping the cache and duplicate disposal',async()=>{const f=await fixture('odd'),r=await segmentedStereogram(f.image,{mode:2},{budget:f.budget});await r.stereoCache.dispose();await r.stereoCache.dispose();const frame=await r.surface.readWindow();assert.equal(hash(frame.pixels.data),f.e.views[2]);frame.release();assert.ok(f.budget.total()>0);await disposeResult(r);await disposeResult(r);assert.equal(f.budget.total(),0);});
test('Native final progress callback cancellation publishes no raster/cache owner',async()=>{for(const phase of['stereo-search','stereo-pattern','stereo-flow-input','stereo-flow','stereo-disparity-render','stereo-triangle']){const f=await fixture('odd'),c=new AbortController();await assert.rejects(segmentedStereogram(f.image,{mode:phase==='stereo-triangle'?1:3},{budget:f.budget,signal:c.signal,blockPixels:512,onProgress:p=>{if(p.phase===phase&&p.completed===p.total)c.abort();}}),{code:'CANCELLED'},phase);assert.equal(f.budget.total(),0,phase);}});
test('Low native budget refusal happens before source IO, reservations roll back',async()=>{const f=await fixture('odd');f.budget.setLimit(4*1024**2);let reads=0;const original=f.image.surface.readWindow;f.image.surface.readWindow=(...a)=>{reads++;return original(...a);};await assert.rejects(segmentedStereogram(f.image,{mode:3},{budget:f.budget}),{code:'MEMORY_LIMIT'});assert.equal(reads,0);assert.equal(f.budget.total(),0);});
test('Preview cannot evict authoritative native work when admission fails',async()=>{const f=await fixture('odd'),r=await segmentedStereogram(f.image,{mode:0},{budget:f.budget});try{const before=f.budget.total(),hold=f.budget.reserve(f.budget.limit-before-1024);try{await assert.rejects(previewCachedStereo(f.image,r.stereoCache,{mode:3},{maxSide:128,maxPixels:16384,maxWorkingBytes:64*1024**2},{budget:f.budget}),{code:'MEMORY_LIMIT'});assert.equal(f.budget.total(),f.budget.limit-1024);}finally{hold();}const frame=await r.surface.readWindow();assert.equal(hash(frame.pixels.data),f.e.views[0]);frame.release();assert.equal(f.budget.total(),before);}finally{await disposeResult(r);await r.stereoCache.dispose();assert.equal(f.budget.total(),0);}});
test('Native changed view cancellation keeps the previously published view usable',async()=>{const f=await fixture('odd'),r=await segmentedStereogram(f.image,{mode:0},{budget:f.budget}),c=new AbortController();try{await assert.rejects(segmentedStereogram(f.image,{mode:3},{budget:f.budget,cache:r.stereoCache,signal:c.signal,onProgress:p=>{if(p.phase==='stereo-disparity-render')c.abort();}}),{code:'CANCELLED'});const frame=await r.surface.readWindow();assert.equal(hash(frame.pixels.data),f.e.views[0]);frame.release();}finally{await disposeResult(r);await r.stereoCache.dispose();assert.equal(f.budget.total(),0);}});
test('Cached-view disposal cancellation cannot publish a completed draft',async()=>{const budget=new Budget(128*1024**2),controller=new AbortController();let leases=0;const pixels={width:4,height:3,format:'rgb8',data:new Uint8Array(36)},master={lease(){leases++;return{async readSampledWindow(){return{pixels,release(){}};},async dispose(){leases--;controller.abort();}};}},image={surface:{descriptor:{width:5,height:3}}},cache={offset:1,views:new Map([[0,master]])};await assert.rejects(previewCachedStereo(image,cache,{mode:0},{maxSide:16,maxPixels:256,maxWorkingBytes:64*1024**2},{budget,signal:controller.signal}),{code:'CANCELLED'});assert.equal(leases,0);assert.equal(budget.total(),0);});
test('Invalid native modes refuse before source IO and before reservations',async()=>{for(const params of[{mode:-1},{mode:4},{mode:1.5},{mode:NaN},{unknown:1}]){const budget=new Budget(128*1024**2);let reads=0;await assert.rejects(segmentedStereogram({surface:{descriptor:{width:96,height:33},readWindow(){reads++;throw Error('unreachable');}}},params,{budget}),{code:'INVALID_INPUT'});assert.equal(reads,0);assert.equal(budget.total(),0);}});
test('Cached-plane read cancellation releases only its borrowed draft workspace',async()=>{const f=await fixture('odd'),r=await segmentedStereogram(f.image,{mode:2},{budget:f.budget}),controller=new AbortController(),plane=r.stereoCache.flow.plane,read=plane.read;let reads=0;const prior=f.budget.total();plane.read=async(...args)=>{const result=await read(...args);if(++reads===2)controller.abort();return result;};try{await assert.rejects(previewCachedStereo(f.image,r.stereoCache,{mode:3},{maxSide:128,maxPixels:16384,maxWorkingBytes:64*1024**2},{budget:f.budget,signal:controller.signal}),{code:'CANCELLED'});assert.equal(reads,2);assert.equal(f.budget.total(),prior);const part=await r.surface.readWindow();assert.equal(hash(part.pixels.data),f.e.views[2]);part.release();}finally{plane.read=read;await disposeResult(r);await r.stereoCache.dispose();assert.equal(f.budget.total(),0);}});
